function lookupRequest({ operation, query }) {
  if (!['column_names', 'column_values', 'row'].includes(operation)) throw new Error('Use column_names, column_values, or row.');
  if (query != null && typeof query !== 'string') throw new Error('The lookup query must be text.');
  const text = query ?? '';
  if (operation === 'column_values' && !text.trim()) throw new Error('Supply the exact column name.');
  if (operation === 'row' && (!/^[1-9]\d*$/.test(text) || !Number.isSafeInteger(Number(text)))) throw new Error('Supply a positive physical row number as text.');
  return { operation, query: text };
}

function prepareSheetLookup({ operation, query, spreadsheetId, range }) {
  const lookup = lookupRequest({ operation, query });
  if (typeof spreadsheetId !== 'string' || !/^[A-Za-z0-9_-]+$/.test(spreadsheetId) || /YOUR_SPREADSHEET_ID/.test(spreadsheetId)) throw new Error('Configure your Google spreadsheet ID before running.');
  if (typeof range !== 'string' || !/^'(?:[^'\u0000-\u001f\u007f]|'')+'$/.test(range)) throw new Error('Configure the complete tab as a single-quoted A1 sheet name.');
  return { ...lookup, spreadsheetId, range };
}

return $input.all().map((item,index)=>({json:prepareSheetLookup(item.json),pairedItem:{item:index}}));

function lookupSheet({ values, majorDimension = 'ROWS', operation, query }) {
  if (majorDimension !== 'ROWS' || !Array.isArray(values) || values.some(row => !Array.isArray(row))) throw new Error('Google Sheets must return row-oriented cell values.');
  const isEmpty = value => value == null || value === '';
  const nonempty = row => row.some(value => !isEmpty(value));
  const headerIndex = values.findIndex(nonempty);
  if (headerIndex < 0) return { response: '[]' };
  const headers = values[headerIndex];
  if (headers.some(name => typeof name !== 'string' || !name.trim() || name === 'row_number') || new Set(headers).size !== headers.length) throw new Error('Use unique nonempty text headers; row_number is reserved.');
  const columns = ['row_number', ...headers];
  const records = [];
  for (let index = headerIndex + 1; index < values.length; index++) {
    const cells = values[index];
    if (!nonempty(cells)) continue;
    if (cells.slice(headers.length).some(value => !isEmpty(value))) throw new Error('Every populated column needs a header.');
    records.push(Object.fromEntries([['row_number', index + 1], ...headers.map((name, column) => [name, cells[column] ?? ''])]));
  }
  let result;
  if (operation === 'column_names') result = columns;
  else if (operation === 'column_values') {
    if (!columns.includes(query)) throw new Error('The requested column does not exist.');
    result = records.map(record => Object.fromEntries([['row_number', record.row_number], [query, record[query]]]));
  } else if (operation === 'row') result = records.filter(record => record.row_number === Number(query));
  else throw new Error('Use column_names, column_values, or row.');
  return { response: JSON.stringify(result) };
}

function formatSheetLookup(input) {
  return lookupSheet(input);
}

return $input.all().map((item,index)=>({json:lookupSheet({...$("Prepare Lookup Query").itemMatching(index).json,values:item.json.values??[],majorDimension:item.json.majorDimension??"ROWS"}),pairedItem:{item:index}}));
